// Build the digest with code. No AI, no tokens.
const today = $('Get today\'s numbers').all()[0]?.json ?? {};
const t = Array.isArray(today) ? (today[0] ?? {}) : today;
const errs = $('Get errors').all().map(i => i.json).flat().filter(Boolean);

const d = new Date().toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Asia/Kolkata' });
const n = (v) => (v === null || v === undefined ? 0 : v);

const lines = [
  `Sidana AI - ${d}`,
  '',
  `Deals sent:       ${n(t.deals_sent)}`,
  `Meetings booked:  ${n(t.meetings_booked)}  (${n(t.second_meetings)} second)`,
  `Replies:          ${n(t.replies_in)}  (${n(t.replies_interested)} interested, ${n(t.replies_pass)} pass)`,
  `Docs received:    ${n(t.docs_in)}`,
  `Investors added:  ${n(t.investors_added)}`,
  `Cost:             $${Number(n(t.cost_usd_today)).toFixed(2)}`,
  ''
];

if (errs.length) {
  lines.push(`ERRORS (${errs.length}):`);
  errs.forEach(e => lines.push(`  - ${e.workflow}${e.entity_name ? ' on ' + e.entity_name : ''}: ${e.error_msg || 'no message'}`));
} else {
  lines.push('No errors.');
}

return [{ json: { subject: `Sidana AI - ${d}${errs.length ? ' - ' + errs.length + ' errors' : ''}`, body: lines.join('\n') } }];
